const $=id=>document.getElementById(id);let lang='ka',theme='neon';try{lang=localStorage.getItem('playerone-lang')||lang;theme=localStorage.getItem('playerone-theme')||theme}catch{}if(!T[lang])lang='ka';if(!['neon','studio'].includes(theme))theme='neon';
function setLang(l){lang=l;const t=T[l];document.documentElement.lang=l;document.querySelectorAll('[data-t]').forEach(e=>e.innerHTML=t[e.dataset.t]);document.querySelectorAll('[data-lang]').forEach(b=>{b.classList.toggle('active',b.dataset.lang===l);b.setAttribute('aria-pressed',String(b.dataset.lang===l))});$('closeBooking').setAttribute('aria-label',t.close);document.querySelector('.themes').setAttribute('aria-label',t.design);document.querySelector('.langs').setAttribute('aria-label',t.language);document.querySelector('.games').setAttribute('aria-label',t.gallery);$('result').hidden=true;$('error').textContent='';try{localStorage.setItem('playerone-lang',l)}catch{}}
function setTheme(value){theme=value;document.body.classList.toggle('studio',value==='studio');document.querySelectorAll('[data-theme]').forEach(b=>{b.classList.toggle('active',b.dataset.theme===value);b.setAttribute('aria-pressed',String(b.dataset.theme===value))});document.querySelector('meta[name="theme-color"]').content=value==='studio'?'#eeeee7':'#101113';try{localStorage.setItem('playerone-theme',value)}catch{}}
function openBooking(game){if(game)$('game').value=game;$('result').hidden=true;$('error').textContent='';$('date').min=localDate(new Date());$('bookingDialog').showModal()}
const localDate=d=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Tbilisi',year:'numeric',month:'2-digit',day:'2-digit'}).format(d);
document.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>setLang(b.dataset.lang));document.querySelectorAll('[data-theme]').forEach(b=>b.onclick=()=>setTheme(b.dataset.theme));document.querySelectorAll('[data-game]').forEach(b=>b.onclick=()=>openBooking(b.dataset.game));document.querySelectorAll('[data-book]').forEach(b=>b.onclick=()=>openBooking());$('closeBooking').onclick=()=>$('bookingDialog').close();$('bookingDialog').addEventListener('click',e=>{if(e.target===$('bookingDialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
$('date').min=localDate(new Date());$('date').value=localDate(new Date());$('hours').onchange=()=>{$('estimate').textContent=Number($('hours').value)*10+' ₾';$('result').hidden=true};$('bookingForm').addEventListener('input',()=>{$('result').hidden=true;$('error').textContent=''});
$('bookingForm').onsubmit=e=>{e.preventDefault();const t=T[lang],when=new Date($('date').value+'T'+$('time').value+':00+04:00');if(!Number.isFinite(+when)||when<=new Date()){$('error').textContent=t.past;return}$('error').textContent='';$('summary').value=['PLAYER ONE · '+t.request,t.name+': '+$('name').value.trim(),t.game+': '+$('game').value,t.date+': '+$('date').value,t.time+': '+$('time').value,t.duration+': '+$('hours').value,t.players+': '+$('players').value,t.total+': '+Number($('hours').value)*10+' GEL',t.requestNote].join('\n');$('result').hidden=false;$('copyStatus').textContent='';$('result').scrollIntoView({behavior:'smooth',block:'nearest'})};$('copy').onclick=async()=>{try{await navigator.clipboard.writeText($('summary').value);$('copyStatus').textContent=T[lang].copied}catch{$('summary').select();$('copyStatus').textContent=T[lang].copyFail}};setLang(lang);setTheme(theme);
